import fs from "node:fs";
import path from "node:path";

export const REPO_ROOT = path.resolve(import.meta.dirname, "../..");

export const GENERATED_HEADER =
  "# GENERATED BY pnpm env:sync — do not edit. Edit env/values/<profile>.json and env/manifest.json instead.\n";

export function parseEnvFile(content) {
  const entries = {};
  const order = [];

  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) {
      continue;
    }
    const eq = trimmed.indexOf("=");
    if (eq === -1) {
      continue;
    }
    const key = trimmed.slice(0, eq).trim();
    if (!key) {
      continue;
    }
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith("'") && value.endsWith("'")) ||
      (value.startsWith('"') && value.endsWith('"'))
    ) {
      value = value.slice(1, -1);
    }
    entries[key] = value;
    if (!order.includes(key)) {
      order.push(key);
    }
  }

  return { entries, order };
}

export function formatEnvValue(value) {
  if (value === undefined || value === null) {
    return "";
  }
  const stringValue = String(value);
  if (stringValue === "") {
    return "";
  }
  if (/[\s#'"\\]/.test(stringValue)) {
    return `'${stringValue.replace(/'/g, "'\\''")}'`;
  }
  return stringValue;
}

export function serializeEnvFile(keys, resolveValue) {
  const lines = [GENERATED_HEADER.trimEnd()];
  for (const key of keys) {
    const value = resolveValue(key);
    if (value === undefined) {
      throw new Error(`Missing value for ${key}`);
    }
    lines.push(`${key}=${formatEnvValue(value)}`);
  }
  lines.push("");
  return `${lines.join("\n")}`;
}

export function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

export function writeJson(filePath, data) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(data, null, 2)}\n`, "utf8");
}

export function loadProfileValues(profile) {
  const valuesPath = path.join(REPO_ROOT, "env", "values", `${profile}.json`);
  if (!fs.existsSync(valuesPath)) {
    throw new Error(
      `Missing ${valuesPath}. Run pnpm env:import to bootstrap from existing .env files.`,
    );
  }
  const data = readJson(valuesPath);
  if (!data.values || typeof data.values !== "object") {
    throw new Error(`${valuesPath} must contain a "values" object.`);
  }
  return data.values;
}

export function loadManifest() {
  const manifestPath = path.join(REPO_ROOT, "env", "manifest.json");
  return readJson(manifestPath);
}

export function resolveTargetValue(key, sharedValues, overrides) {
  if (overrides && Object.prototype.hasOwnProperty.call(overrides, key)) {
    return overrides[key];
  }
  if (Object.prototype.hasOwnProperty.call(sharedValues, key)) {
    return sharedValues[key];
  }
  return undefined;
}

export function buildTargetContent(targetName, targetConfig, sharedValues) {
  const keys = targetConfig.keys;
  const overrides = targetConfig.overrides ?? {};
  if (!Array.isArray(keys) || keys.length === 0) {
    throw new Error(`Target ${targetName} must define a non-empty "keys" array.`);
  }
  return serializeEnvFile(keys, (key) => resolveTargetValue(key, sharedValues, overrides));
}

export function parseArgs(argv) {
  const args = { profile: "all", dryRun: false, write: true };
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === "--dry-run") {
      args.dryRun = true;
      args.write = false;
    } else if (token === "--profile") {
      args.profile = argv[i + 1];
      i += 1;
    } else if (token === "--help" || token === "-h") {
      args.help = true;
    }
  }
  return args;
}
